import{_ as a,C as e,c as o,o as i,a0 as r,b as t,w as s,a as n,G as l,a1 as u}from"./chunks/framework.DKRgXLPU.js";const c=JSON.parse('{"title":"Comunicação em equipe","description":"","frontmatter":{},"headers":[],"relativePath":"pt/education/team-player/communication.md","filePath":"pt/education/team-player/communication.md"}');const d=a({name:"pt/education/team-player/communication.md"},[["render",function(a,c,d,m,p,h){const q=e("Mermaid");return i(),o("div",null,[c[1]||(c[1]=r('<h1 id="comunicacao-em-equipe" tabindex="-1">Comunicação em equipe <a class="header-anchor" href="#comunicacao-em-equipe" aria-label="Permalink to &quot;Comunicação em equipe&quot;">​</a></h1><p>A comunicação eficaz é o que transforma um grupo de indivíduos em uma equipe. Na petanca, onde a estratégia muda constantemente e a pressão é alta, a forma como você se comunica pode determinar o resultado.</p><div class="tip custom-block"><p class="custom-block-title">A Grande Ideia</p><p><strong>A comunicação é o que transforma indivíduos em uma equipe.</strong> Uma comunicação clara, específica e de apoio sob pressão diferencia as boas equipes das excelentes.</p></div><h2 id="o-ciclo-de-comunicacao" tabindex="-1">O Ciclo de Comunicação <a class="header-anchor" href="#o-ciclo-de-comunicacao" aria-label="Permalink to &quot;O Ciclo de Comunicação&quot;">​</a></h2><p>Uma boa comunicação em equipe segue um ciclo:</p>',5)),(i(),t(u,null,{default:s(()=>[l(q,{id:"mermaid-17",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BObservar%5D%20--%3E%20B%5BCompartilhar%5D%0A%20%20%20%20B%20--%3E%20C%5BDiscutir%5D%0A%20%20%20%20C%20--%3E%20D%5BDecidir%5D%0A%20%20%20%20D%20--%3E%20E%5BExecutar%5D%0A%20%20%20%20E%20--%3E%20F%5BAn%C3%A1lise%5D%0A%20%20%20%20F%20--%3E%20A%0A%0A%20%20%20%20style%20A%20fill%3A%23e3f2fd%0A%20%20%20%20style%20D%20fill%3A%23e8f5e9%0A%20%20%20%20style%20E%20fill%3A%23fff4e1%0A%20%20%20%20style%20F%20fill%3A%23f3e5f5%0A"})]),fallback:s(()=>[...c[0]||(c[0]=[n(" Loading... ",-1)])]),_:1})),c[2]||(c[2]=r('<table tabindex="0"><thead><tr><th>Etapa</th><th>Ação</th><th>Exemplo</th></tr></thead><tbody><tr><td><strong>Observar</strong></td><td>Observe o que está acontecendo</td><td>Terreno, posições, adversários</td></tr><tr><td><strong>Compartilhar</strong></td><td>Compartilhe com seus colegas o que você vê.</td><td>&quot;O terreno se inclina para a esquerda ali&quot;</td></tr><tr><td><strong>Discutir</strong></td><td>Trocar perspectivas</td><td>&quot;Devo bloquear ou tentar o ponto?&quot;</td></tr><tr><td><strong>Decidir</strong></td><td>Concordar com a abordagem.</td><td>&quot;Vamos tentar o passe alto&quot;</td></tr><tr><td><strong>Executar</strong></td><td>Faça isso com comprometimento.</td><td>Foco total no arremesso</td></tr><tr><td><strong>Análise</strong></td><td>Aprenda com os resultados.</td><td>&quot;Isso funcionou bem&quot; ou &quot;Na próxima vez...&quot;</td></tr></tbody></table><h2 id="quando-comunicar" tabindex="-1">Quando comunicar <a class="header-anchor" href="#quando-comunicar" aria-label="Permalink to &quot;Quando comunicar&quot;">​</a></h2><h3 id="antes-de-cada-fim" tabindex="-1">Antes de cada fim <a class="header-anchor" href="#antes-de-cada-fim" aria-label="Permalink to &quot;Antes de cada fim&quot;">​</a></h3><ul><li>Avalie o terreno juntos</li><li>Discuta a abordagem geral.</li><li>Esclareça quem vai arremessar e quando.</li><li>Defina o tom (calmo, concentrado)</li></ul><h3 id="durante-o-fim" tabindex="-1">Durante o Fim <a class="header-anchor" href="#durante-o-fim" aria-label="Permalink to &quot;Durante o Fim&quot;">​</a></h3><ul><li>Compartilhe suas observações (&quot;O terreno inclina-se para a esquerda ali&quot;)</li><li>Estratégia coordenada (&quot;Devo tentar bloquear ou partir para o ponto?&quot;)</li><li>Ofereça apoio (&quot;Não se apresse, você consegue&quot;)</li><li>Ajuste os planos conforme a situação mudar.</li></ul><h3 id="entre-extremidades" tabindex="-1">Entre extremidades <a class="header-anchor" href="#entre-extremidades" aria-label="Permalink to &quot;Entre extremidades&quot;">​</a></h3><ul><li>Breve resumo (o que funcionou, o que não funcionou)</li><li>Reiniciar mentalmente</li><li>Prepare-se para o próximo fim</li><li>Mantenham-se conectados como equipe.</li></ul><h3 id="apos-o-jogo" tabindex="-1">Após o jogo <a class="header-anchor" href="#apos-o-jogo" aria-label="Permalink to &quot;Após o jogo&quot;">​</a></h3><ul><li>Debriefing completo (quando apropriado)</li><li>Agradecer as contribuições</li><li>Identificar aprendizados</li><li>Manter relacionamento</li></ul><h2 id="como-se-comunicar" tabindex="-1">Como se comunicar <a class="header-anchor" href="#como-se-comunicar" aria-label="Permalink to &quot;Como se comunicar&quot;">​</a></h2><h3 id="seja-claro-e-especifico" tabindex="-1">Seja claro e específico. <a class="header-anchor" href="#seja-claro-e-especifico" aria-label="Permalink to &quot;Seja claro e específico.&quot;">​</a></h3><p><strong>Vago:</strong> &quot;Tente se aproximar&quot; <strong>Instruções:</strong> &quot;Mire no lado esquerdo do macaco, a cerca de 20 cm de distância&quot;</p><p><strong>Vago:</strong> &quot;Boa tentativa&quot; <strong>Limpo:</strong> &quot;Bom peso, apenas um pouco à esquerda da linha&quot;</p><h3 id="seja-construtivo" tabindex="-1">Seja construtivo <a class="header-anchor" href="#seja-construtivo" aria-label="Permalink to &quot;Seja construtivo&quot;">​</a></h3><p>Foque nas soluções, não nos problemas:</p><p><strong>Focado no problema:</strong> &quot;Você continua errando para a direita&quot; <strong>Focado na solução:</strong> &quot;Talvez tente mirar um pouco mais para a esquerda para compensar?&quot;</p><h3 id="seja-solidario" tabindex="-1">Seja solidário <a class="header-anchor" href="#seja-solidario" aria-label="Permalink to &quot;Seja solidário&quot;">​</a></h3><p>Seu tom de voz importa tanto quanto suas palavras:</p><ul><li>Mantenha a calma, mesmo quando estiver frustrado.</li><li>Use linguagem corporal encorajadora.</li><li>Reconheça o esforço, não apenas os resultados.</li><li>Construa, não destrua.</li></ul><h3 id="escute-ativamente" tabindex="-1">Escute ativamente <a class="header-anchor" href="#escute-ativamente" aria-label="Permalink to &quot;Escute ativamente&quot;">​</a></h3><p>A comunicação é bidirecional:</p><ul><li>Preste total atenção quando seus colegas de equipe estiverem falando.</li><li>Faça perguntas para esclarecer.</li><li>Reconheça o que você ouviu.</li><li>Não interrompa nem dispense.</li></ul><h2 id="desafios-de-comunicacao" tabindex="-1">Desafios de comunicação <a class="header-anchor" href="#desafios-de-comunicacao" aria-label="Permalink to &quot;Desafios de comunicação&quot;">​</a></h2><h3 id="divergencia-sobre-a-estrategia" tabindex="-1">Divergência sobre a estratégia <a class="header-anchor" href="#divergencia-sobre-a-estrategia" aria-label="Permalink to &quot;Divergência sobre a estratégia&quot;">​</a></h3><p><strong>Abordagem inadequada:</strong></p><ul><li>Insista em seguir o seu caminho.</li><li>Adote uma postura defensiva.</li><li>Ceder com ressentimento</li><li>Discutir durante o jogo</li></ul><p><strong>Melhor abordagem:</strong></p><ol><li>Compartilhe sua perspectiva com clareza.</li><li>Ouça atentamente o que eles têm a dizer.</li><li>Discuta brevemente as vantagens e desvantagens.</li><li>Decidam juntos (ou deixem a decisão para o líder designado).</li><li>Comprometa-se totalmente com a decisão.</li><li>Análise após o jogo</li></ol><h3 id="apos-o-erro-de-um-companheiro-de-equipe" tabindex="-1">Após o erro de um companheiro de equipe <a class="header-anchor" href="#apos-o-erro-de-um-companheiro-de-equipe" aria-label="Permalink to &quot;Após o erro de um companheiro de equipe&quot;">​</a></h3><p><strong>Do que eles precisam:</strong></p><ul><li>Reconhecimento rápido</li><li>Permissão para prosseguir.</li><li>A confiança de que você ainda confia neles.</li><li>Concentre-se no próximo arremesso.</li></ul><p><strong>O que dizer:</strong></p><ul><li>&quot;Sem problema, próximo.&quot;</li><li>&quot;Que azar, mas você tem o próximo.&quot;</li><li>&quot;Ainda estamos nisso&quot;</li><li>Às vezes, um aceno de cabeça ou um tapinha já bastam.</li></ul><p><strong>O que NÃO dizer:</strong></p><ul><li>Nada (o silêncio parece um julgamento)</li><li>&quot;Está tudo bem&quot; (pode soar como alguém que ignora o problema)</li><li>Qualquer informação sobre o que deu errado (não agora).</li><li>Frustração visível (a linguagem corporal conta)</li></ul><h3 id="quando-voce-comete-um-erro" tabindex="-1">Quando você comete um erro <a class="header-anchor" href="#quando-voce-comete-um-erro" aria-label="Permalink to &quot;Quando você comete um erro&quot;">​</a></h3><p><strong>O que fazer:</strong></p><ul><li>Breve agradecimento (&quot;Foi mal&quot;)</li><li>Não peça desculpas em excesso.</li><li>Não dê desculpas.</li><li>Recomece e concentre-se no próximo arremesso.</li><li>Confie que seus colegas de equipe te apoiarão.</li></ul><h3 id="tensao-na-equipe" tabindex="-1">Tensão na equipe <a class="header-anchor" href="#tensao-na-equipe" aria-label="Permalink to &quot;Tensão na equipe&quot;">​</a></h3><p>Se a tensão aumentar durante um jogo:</p><ol><li>Reconheça que está acontecendo.</li><li>Respire fundo antes de responder.</li><li>Concentre-se no jogo, não no conflito.</li><li>Aborde o assunto adequadamente após o jogo.</li><li>Não deixe que isso afete seu jogo.</li></ol><h2 id="comunicacao-nao-verbal" tabindex="-1">Comunicação não verbal <a class="header-anchor" href="#comunicacao-nao-verbal" aria-label="Permalink to &quot;Comunicação não verbal&quot;">​</a></h2><p>Grande parte da comunicação em equipe é não verbal:</p><h3 id="sinais-positivos" tabindex="-1">Sinais Positivos <a class="header-anchor" href="#sinais-positivos" aria-label="Permalink to &quot;Sinais Positivos&quot;">​</a></h3><ul><li>Contato visual</li><li>Acenando com a cabeça</li><li>Afirmativo</li><li>postura relaxada</li><li>Aproximando-se dos companheiros de equipe</li><li>Sorrir (quando apropriado)</li></ul><h3 id="sinais-negativos-evite-os" tabindex="-1">Sinais negativos (evite-os) <a class="header-anchor" href="#sinais-negativos-evite-os" aria-label="Permalink to &quot;Sinais negativos (evite-os)&quot;">​</a></h3><ul><li>Revirar os olhos</li><li>Virando as costas</li><li>Braços cruzados</li><li>Suspirando</li><li>Balançando a cabeça</li><li>linguagem corporal tensa</li></ul><p><strong>Lembre-se:</strong> Seus colegas de equipe veem tudo. Sua linguagem corporal afeta a confiança e o desempenho deles.</p><h2 id="desenvolvendo-habitos-de-comunicacao" tabindex="-1">Desenvolvendo Hábitos de Comunicação <a class="header-anchor" href="#desenvolvendo-habitos-de-comunicacao" aria-label="Permalink to &quot;Desenvolvendo Hábitos de Comunicação&quot;">​</a></h2><h3 id="praticar-a-comunicacao" tabindex="-1">Praticar a comunicação <a class="header-anchor" href="#praticar-a-comunicacao" aria-label="Permalink to &quot;Praticar a comunicação&quot;">​</a></h3><p>Não espere que a concorrência se comunique:</p><ul><li>Praticar discussões estratégicas em treinamentos</li><li>Dêem feedback uns aos outros regularmente</li><li>Desenvolva a linguagem da sua equipe.</li><li>Construa um relacionamento confortável através de conversas honestas.</li></ul><h3 id="desenvolver-sinais-de-equipe" tabindex="-1">Desenvolver sinais de equipe <a class="header-anchor" href="#desenvolver-sinais-de-equipe" aria-label="Permalink to &quot;Desenvolver sinais de equipe&quot;">​</a></h3><p>Algumas equipes desenvolvem taquigrafia:</p><ul><li>Sinais com as mãos para estratégia</li><li>Códigos para situações</li><li>Frases curtas com significado compartilhado</li></ul><h3 id="check-ins-regulares" tabindex="-1">Check-ins regulares <a class="header-anchor" href="#check-ins-regulares" aria-label="Permalink to &quot;Check-ins regulares&quot;">​</a></h3><p>Fora dos jogos:</p><ul><li>Como estamos trabalhando juntos?</li><li>O que está indo bem?</li><li>O que poderia ser melhor?</li><li>Há algum problema a ser resolvido?</li></ul><h2 id="o-papel-do-capitao" tabindex="-1">O papel do capitão <a class="header-anchor" href="#o-papel-do-capitao" aria-label="Permalink to &quot;O papel do capitão&quot;">​</a></h2><p>Se sua equipe tiver um líder designado:</p><p><strong>Responsabilidades do capitão:</strong></p><ul><li>Decisão final quando a equipe discorda.</li><li>Definindo o tom e a energia.</li><li>Gerenciando a dinâmica da equipe</li><li>Manter o foco sob pressão</li></ul><p><strong>Todos os outros:</strong></p><ul><li>Compartilhe sua perspectiva.</li><li>Apoie a decisão tomada.</li><li>Ajude a manter a energia da equipe.</li><li>Assuma a responsabilidade pelo seu papel.</li></ul><h2 id="ponto-chave" tabindex="-1">Ponto-chave <a class="header-anchor" href="#ponto-chave" aria-label="Permalink to &quot;Ponto-chave&quot;">​</a></h2><blockquote><p>Grandes equipes conversam entre si, não falam umas das outras. Elas se comunicam com honestidade, respeito e um compromisso compartilhado com o sucesso.</p></blockquote><p>Pratique a comunicação como você pratica arremessos. É uma habilidade que melhora com atenção.</p>',68))])}]]);export{c as __pageData,d as default};
